sourceSnippets.canonicalStamp:
function canonicalStamp(v){
  const n=normText(v||'');
  if(!n||n==='none'||n==='nessuno')return 'None';
  if(n.includes('play')||n.includes('player reward')||n.includes('prize pack'))return 'Play! Pokémon';
  if(n.includes('pokemon day'))return 'Pokémon Day';
  if(n.includes('30 anniversario')||n.includes('30th celebration')||n.includes('30 celebration'))return '30° Anniversario';
  if(n.includes('pokemon center'))return 'Pokémon Center';
  if(n.includes('pre-release')||n.includes('prerelease'))return 'Pre-release';
  if(n.includes('staff'))return 'Staff';
  if(n.includes('set stamp')||n.includes('set-promo'))return 'Set Stamp';
  if(n.includes('gamestop'))return 'GameStop';
  return v||'Altro';
}

sourceSnippets.tcgdexVariantDetails:
function tcgdexVariantDetails(card){
  if(Array.isArray(card?.variants_detailed))return card.variants_detailed;
  if(Array.isArray(card?.variants))return card.variants;
  return [];
}

sourceSnippets.stampEvidenceFromTCGdex:
function stampEvidenceFromTCGdex(card,stamp){
  const st=canonicalStamp(stamp);
  const list=tcgdexVariantDetails(card);
  // TCGdex uses the exact `set-logo` taxonomy for set-logo promos.  Staff
  // copies also carry `set-logo`, so a plain Set Stamp must explicitly exclude
  // rows that also carry `staff`.  If this taxonomy is absent, preserve the
  // older lexical aliases below.
  if(st==='Set Stamp'){
    const setLogoRows=list.filter(x=>(Array.isArray(x?.stamp)?x.stamp:[]).map(normText).includes('setlogo'));
    if(setLogoRows.length){
      return setLogoRows.some(x=>!(Array.isArray(x?.stamp)?x.stamp:[]).map(normText).includes('staff'));
    }
  }
  const tokens={
    'Play! Pokémon':['playerrewards','playpokemon','prizepack','league'],
    'Pokémon Day':['pokemonday'],
    '30° Anniversario':['30thcelebration','30anniversario','30thanniversary'],
    'Pokémon Center':['pokemoncenter'],
    'Pre-release':['prerelease','prereleasepromo'],
    'Staff':['staff'],
    'Set Stamp':['setstamp','setpromo'],
    'GameStop':['gamestop']
  }[st]||[];
  if(!tokens.length)return false;
  return list.some(x=>{
    const vals=[...(Array.isArray(x?.stamp)?x.stamp:[]),x?.foil,x?.name,x?.variant].filter(Boolean).map(normText);
    return vals.some(v=>tokens.some(t=>v.includes(t)));
  });
}

sourceSnippets.verifiedStampPrice:
function verifiedStampPrice(card,variant,stamp){
  const exact=verifiedExactSpecialStampPrice(card,variant,stamp);
  if(exact)return exact;
  const tcgdexExact=tcgdexExactSvpStampPrice(card,variant,stamp);
  if(tcgdexExact)return tcgdexExact;
  const setName=normText(card?.set?.name||card?.set||'');
  const num=(String(card?.localId||'').replace(/^0+/,'')||String(card?.localId||''));
  const finish=canonicalVariant(variant||'Normal');
  const st=canonicalStamp(stamp||'None');
  for(const [k,v] of Object.entries(VERIFIED_STAMP_PRICES)){
    const [ks,kn,kf,kst]=k.split('|');
    if(normText(ks)===setName &&
       String(kn).replace(/^0+/,'')===num &&
       kf===finish && kst===st)return v;
  }
  return null;
}

sourceSnippets.verifiedExactSpecialStampPrice:
function verifiedExactSpecialStampPrice(card,variant,stamp){
  const id=String(card?.tcgdexId||card?.id||'').trim().toLowerCase();
  const rule=VERIFIED_EXACT_SPECIAL_STAMP_PRICES[id];
  if(!rule || cardSetId(card)!==rule.setId ||
     exactLocalIdKey(card?.localId||'')!==exactLocalIdKey(rule.localId) ||
     normText(card?.name||'')!==normText(rule.name||'') ||
     canonicalVariant(variant||'Normal')!==canonicalVariant(rule.finish) ||
     canonicalStamp(stamp||'None')!==canonicalStamp(rule.stamp))return null;
  return rule;
}

sourceSnippets.tcgdexExactSvpStampPrice:
function tcgdexExactSvpStampPrice(card,variant,stamp){
  const setId=normText(card?.set?.id||card?._cardoryxSetId||card?.setId||'');
  if(setId!=='svp'&&setId!=='mep')return null;
  const st=canonicalStamp(stamp);
  if(st!=='Set Stamp'&&st!=='Staff')return null;
  const target=canonicalVariant(variant||'Normal');
  const rows=tcgdexVariantDetails(card).filter(x=>{
    if(Array.isArray(x?.languages)&&x.languages.length&&!x.languages.includes('it'))return false;
    const stamps=(Array.isArray(x?.stamp)?x.stamp:[]).map(normText);
    const exactStamp=st==='Set Stamp'
      ? stamps.includes('setlogo')&&!stamps.includes('staff')
      : stamps.includes('setlogo')&&stamps.includes('staff');
    return exactStamp&&tcgdexStampedRowFinish(x)===target;
  });
  if(rows.length!==1)return null;
  const row=rows[0];
  const productId=Number(row?.thirdParty?.cardmarket||0);
  const cm=row?.pricing?.cardmarket;
  const pricingProductId=Number(cm?.idProduct||cm?.id_product||0);
  if(!(productId>0)||!cm||pricingProductId!==productId)return null;
  const hasRealPrice=['trend','avg7','avg30','avg','low'].some(k=>Number(cm?.[k])>0);
  if(!hasRealPrice)return null;
  return {...cm,idProduct:productId,source:`TCGdex · Cardmarket · ${st}`,verified:String(cm?.updated||'')};
}

sourceSnippets.tcgdexMarketplaceVariant:
function tcgdexMarketplaceVariant(card,variant){
  const target=canonicalVariant(variant||'Normal');
  const list=Array.isArray(card?.variants_detailed)?card.variants_detailed:[];
  const it=list.filter(x=>!Array.isArray(x?.languages)||x.languages.includes('it'));
  const pool=it.length?it:list;
  const hasStamp=(x,name)=>(x?.stamp||[]).some(v=>normText(v)===normText(name));
  let matches=[];
  if(target==='Play! Pokémon Prize Pack'||target==='Play! Pokémon Stamp') matches=pool.filter(x=>hasStamp(x,'player-rewards-program')||x?.foil==='player-reward'||x?.foil==='league');
  else if(target==='Pokémon Day Stamp') matches=pool.filter(x=>hasStamp(x,'pokemon-day'));
  else if(target==='Poké Ball Reverse Holo') matches=pool.filter(x=>x?.type==='reverse'&&x?.foil==='pokeball');
  else if(target==='Master Ball Reverse Holo') matches=pool.filter(x=>x?.type==='reverse'&&x?.foil==='masterball');
  else if(target==='Holo') matches=pool.filter(x=>canonicalFinishTypeLabel(x?.type)==='holo'&&!canonicalFinishFoilLabel(x?.foil)&&!x?.stamp?.length);
  else if(target==='Ditto Peelable') matches=pool.filter(x=>isPeelableDittoVariantRow(x)&&!canonicalFinishFoilLabel(x?.foil)&&!x?.stamp?.length);
  else if(target==='Reverse Holo') matches=pool.filter(x=>canonicalFinishTypeLabel(x?.type)==='reverse'&&!isPeelableDittoVariantRow(x)&&!canonicalFinishFoilLabel(x?.foil)&&!x?.stamp?.length);
  else if(target==='Normal') matches=pool.filter(x=>canonicalFinishTypeLabel(x?.type)==='normal'&&!canonicalFinishFoilLabel(x?.foil)&&!x?.stamp?.length);
  const withCM=matches.find(x=>Number(x?.thirdParty?.cardmarket)>0);
  if(target==='Ditto Peelable')return withCM||null;
  return withCM||matches[0]||null;
}

sourceSnippets.staticProductToPrice:
function staticProductToPrice(p,finish){
  if(!p)return null;
  const f=canonicalVariant(finish||'Normal');
  const wantsHolo=['Holo','Cosmos Holo','Reverse Holo'].includes(f);
  const q=p.prices||{};

  // V1.9.3 — NON usare mai il prezzo Normal come fallback per una finitura Holo.
  // Se Cardmarket non pubblica campi *-holo per quel prodotto, quella finitura
  // non viene considerata verificata/esistente dal resolver Play!.
  const holoLow=numOrNull(q['low-holo']);
  const holoTrend=numOrNull(q['trend-holo']);
  const holoAvg7=numOrNull(q['avg7-holo']);
  const holoAvg30=numOrNull(q['avg30-holo']);
  const hasHoloPrice=[holoLow,holoTrend,holoAvg7,holoAvg30].some(v=>v!=null);
  if(wantsHolo && !hasHoloPrice)return null;

  const low=wantsHolo?holoLow:numOrNull(q.low);
  const trend=wantsHolo?holoTrend:numOrNull(q.trend);
  const avg7=wantsHolo?holoAvg7:numOrNull(q.avg7);
  const avg30=wantsHolo?holoAvg30:numOrNull(q.avg30);
  const value=trend??avg7??avg30??low;
  if(value==null)return null;
  return {idProduct:Number(p.idProduct),low,trend,avg7,avg30,value,exact:true,source:'Cardmarket · indice ufficiale statico',updated:p.updated||''};
}
